// Bearer <token de sessao> no cabecalho; o token FCM vem no corpo.
// A mesma funcao atende as duas rotas: a URL diz se e para remover.
const auth = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const sess = auth.replace(/^Bearer\s+/i, '').trim();
const fcm = String((msg.payload || {}).fcm_token || '').trim();
if (!sess || !fcm) {
    msg.statusCode = 400;
    msg.payload = { error: 'missing' };
    return [null, msg];
}
const remover = String(msg.req.url || '').indexOf('unregister') >= 0;
msg.params = [sess, fcm, remover];
return [msg, null];

const row = (msg.payload && msg.payload[0]) || {};
if (row.status === 'ok') {
    msg.statusCode = 200;
    msg.payload = { ok: true };
} else {
    msg.statusCode = 401;
    msg.payload = { error: row.status || 'unauthorized' };
}
return msg;
